Clear[a, b, c, x, yp, pol]
yp[x_] = a + b*x + c*x^2;
pol = D[yp[x], {x, 3}] + D[yp[x], {x, 2}] + 2 D[yp[x], x] - 4 yp[x];
Collect[pol, x]   (* agrupa por potencias de x para comparar con 2 x^2 + x - 1 *)
sol = Solve[{-4 a + 2 b + 2 c == -1, -4 b + 4 c == 1, -4 c == 2}, {a, b, c}]
a /. Flatten[sol] // N

