g[t_] = UnitStep[t - Pi/2]*Cos[t];
ec1 = LaplaceTransform[y''[t] + y[t] == g[t], t, s] /. {y[0] -> 10, y'[0] -> 0};
sol1 = Solve[ec1, LaplaceTransform[y[t], t, s]];
