Clear[a, b, c, f, int, u, x, y, C1]
(* primer factor: (Dx - Dy + 1) u = 4 x E^(-2 y) *)
a = 1; b = -1; c = 1; f[x_, y_] = 4 x*Exp[-2 y];
int[x_, C1_] = Exp[-c*x/a]/a*Integrate[Exp[c*x/a]*f[x, (C1 + b*x)/a], x];
u[x_, y_] = int[x, a*y - b*x] // Simplify
